WITH filtered AS (SELECT id, customer_id, account_type, balance, status, LAST_DAY(opened_date) AS opened_date_month_end, COALESCE(status, 'N/A') AS resolved_status FROM accounts WHERE status IS NOT NULL AND opened_date >= DATE '2023-08-19') SELECT p.segment, p.city, COUNT(*) AS num_rows, ROUND(SUM(a.balance), 2) AS total_balance, GROUPING_ID() AS level_id FROM filtered a INNER JOIN customers p ON a.customer_id = p.id GROUP BY GROUPING SETS ((p.segment, p.city), (p.segment)) ORDER BY segment NULLS LAST
